import{c as t,U as s,j as r,g as a,o as i,a6 as o,n as p}from"./chunks/framework.h4W4t1IS.js";const f=JSON.parse('{"title":"Hiérarchie des exceptions","description":"","frontmatter":{"title":"Hiérarchie des exceptions","status":"ready","tags":["exceptions","exceptions-hierarchie","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"exceptions/hierarchie.md","filePath":"exceptions/hierarchie.md"}'),c={name:"exceptions/hierarchie.md"},l={id:"frontmatter-title",tabindex:"-1"};function d(n,e,h,u,m,x){return s(),r("div",null,[a("h1",l,[i(o(n.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=p(`<p>Toutes les <a href="/420-w30-sf-po2/lexique.html#exception" class="lexicon-link" title="Mécanisme qui interrompt le flux normal d&#39;exécution lors d&#39;une situation anormale et remonte la pile d&#39;appels jusqu&#39;à un gestionnaire (catch). Hérite de Throwable.">exceptions</a> Java héritent d&#39;une hiérarchie commune enracinée dans <code>Throwable</code>. Comprendre cette hiérarchie permet de distinguer ce qu&#39;on peut attraper, ce qu&#39;on doit gérer et ce qu&#39;on ne doit jamais attraper.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Identifier la hiérarchie de classes <code>Throwable</code></li><li>Différencier <code>Error</code>, <code>Exception</code> et <code>RuntimeException</code></li></ul></div><h2 id="hierarchie-throwable" tabindex="-1">Hiérarchie Throwable <a class="header-anchor" href="#hierarchie-throwable" aria-label="Permalink to &quot;Hiérarchie Throwable&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Throwable</span></span>
<span class="line"><span>├── Error                      (erreurs JVM - ne jamais attraper)</span></span>
<span class="line"><span>│   ├── OutOfMemoryError</span></span>
<span class="line"><span>│   ├── StackOverflowError</span></span>
<span class="line"><span>│   └── AssertionError</span></span>
<span class="line"><span>└── Exception                  (exceptions gérables)</span></span>
<span class="line"><span>    ├── IOException</span></span>
<span class="line"><span>    │   └── FileNotFoundException</span></span>
<span class="line"><span>    ├── SQLException</span></span>
<span class="line"><span>    ├── ParseException</span></span>
<span class="line"><span>    └── RuntimeException       (non vérifiées - erreurs de programmation)</span></span>
<span class="line"><span>        ├── NullPointerException</span></span>
<span class="line"><span>        ├── IllegalArgumentException</span></span>
<span class="line"><span>        ├── IllegalStateException</span></span>
<span class="line"><span>        ├── ArrayIndexOutOfBoundsException</span></span>
<span class="line"><span>        └── ArithmeticException</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Error - ne jamais attraper</p><p>Les <code>Error</code> représentent des problèmes de la JVM ou de la mémoire qui ne peuvent pas être résolus par le programme. Attraper un <code>OutOfMemoryError</code> ne sert à rien - le programme est dans un état irrécupérable.</p></div><h2 id="deux-branches-sous-exception" tabindex="-1">Deux branches sous Exception <a class="header-anchor" href="#deux-branches-sous-exception" aria-label="Permalink to &quot;Deux branches sous Exception&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Branche</th><th>Vérification par le compilateur</th><th>Sens</th></tr></thead><tbody><tr><td><code>Exception</code> (hors <code>RuntimeException</code>)</td><td><strong>Vérifiée</strong> (checked) - gestion obligatoire</td><td>Situation prévisible et récupérable</td></tr><tr><td><code>RuntimeException</code></td><td><strong>Non vérifiée</strong> (unchecked) - gestion optionnelle</td><td>Erreur de programmation</td></tr></tbody></table><p>Cette distinction détermine si le compilateur oblige à gérer ou déclarer l&#39;exception, ce qui est couvert dans les deux sections suivantes.</p>`,9))])}const g=t(c,[["render",d]]);export{f as __pageData,g as default};
